// Тикет #6a86f800. id DOM (#zman-…-label) заменены текстами: строка = имя + метод (в одном или двух соседних текстах) + время на той же строке.
import { $$, expect, driver } from '@wdio/globals';
import { byText, byTextContains, scrollToText, expectTextContains } from '../../helpers/ui.ts';
import { hasDeepLinks, openRoute } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
/** Минимальный тип элемента (подходит и для WebdriverIO.Element, и для ChainablePromiseElement). */
type El = {
  getAttribute(name: string): Promise<string | null>;
  isSelected(): Promise<boolean>;
  getLocation(): Promise<{ x: number; y: number }>;
  getSize(): Promise<{ width: number; height: number }>;
};

/** Экран «זמני היום»: deep link (APP_SCHEME), иначе — с главной по ссылке/карточке (название уточнить на устройстве). */
async function openZmanim() {
  if (hasDeepLinks()) await openRoute('/zmanim');
  else {
    await toHome();
    for (const name of ['זמני היום', 'זמני התפילות', 'זמנים']) {
      const el = await scrollToText(name, 6).catch(() => null);
      if (el) { await el.click(); break; }
    }
  }
  await (await byTextContains('שקיעת החמה')).waitForDisplayed({ timeout: 25000 });
}
/** Элементы, текст которых содержит подстроку (все). */
function allContains(part: string) {
  return driver.isAndroid
    ? $$(`android=new UiSelector().textContains("${part}")`)
    : $$(`-ios predicate string:label CONTAINS "${part}"`);
}
/** Элементы со временем «H:MM» (возможны невидимые метки направления ‎ вокруг). */
function allTimes() {
  return driver.isAndroid
    ? $$('android=new UiSelector().textMatches(".*\\d{1,2}:\\d{2}.*")')
    : $$('-ios predicate string:label MATCHES ".*[0-9]{1,2}:[0-9]{2}.*"');
}
/** Есть время на той же строке (по вертикали), что и элемент. */
async function timeOnSameLine(el: El) {
  const a = await el.getLocation();
  const h = (await el.getSize()).height;
  for (const t of await allTimes()) {
    const b = await t.getLocation();
    if (Math.abs(b.y - a.y) < Math.max(12, h / 2)) return true;
  }
  return false;
}
/** Строка «<имя> <метод>»: целиком одним текстом либо имя и метод на одной строке; рядом — время. */
async function expectRow(name: string, method: string) {
  await scrollToText(method);
  const full = await byText(`${name} ${method}`);
  if (await full.isDisplayed().catch(() => false)) {
    expect(await timeOnSameLine(full)).toBe(true);
    return;
  }
  for (const m of await allContains(method)) {
    if ((await m.getText()).trim() !== method) continue;
    const my = (await m.getLocation()).y;
    for (const n of await allContains(name)) {
      if (Math.abs((await n.getLocation()).y - my) < 60 && (await timeOnSameLine(n))) return;
    }
  }
  throw new Error(`Не найдена строка «${name} ${method}» со временем`);
}

describe('זמני היום', () => {
  afterEach(async () => { await toHome(); });

  it('ZM-05 «עלות השחר (מג״א, 19.8°)» и «(מג״א, 72 דקות)» в списке вместе с זמנים, что от них считаются #6a86f800 @prod-safe', async () => {
    // 1. «זמני היום» (текущий день).
    await openZmanim();

    // 2. Строки עלות השחר и זמנים по מג״א 19.8°.
    await expectRow('עלות השחר', '(מג״א, 19.8°)');
    await expectRow('עלות השחר', '(בעל התניא)');
    await expectRow('עלות השחר', '(16.1°)');
    await expectRow('עלות השחר', '(מג״א, 72 דקות)');
    await expectRow('סוף זמן קריאת שמע', '(מג״א, 19.8°)');
    await expectRow('סוף זמן תפילה', '(מג״א, 19.8°)');

    // 3. Пояснение под списком.
    await scrollToText('עלות השחר לשיטת מג״א');
    await expectTextContains('עלות השחר לשיטת מג״א חושבה באפליקציה לפי הגדרות Hebcal.');
  });
});
